'use client'

import {
  forwardRef,
  useId,
  type ReactNode,
  type SelectHTMLAttributes,
} from 'react'

export interface SelectProps extends SelectHTMLAttributes<HTMLSelectElement> {
  /** Label text displayed above the select */
  label?: string
  /** Helper text displayed below the select */
  helperText?: string
  /** Error message - when present, select shows error state */
  error?: string
  /** Makes select full width */
  fullWidth?: boolean
  /** Children should be option elements */
  children: ReactNode
}

const baseSelectStyles = `
  w-full rounded-lg border px-3 py-2 pr-10
  text-secondary-900
  transition-colors duration-150
  focus:outline-none focus:ring-2 focus:ring-offset-0
  disabled:cursor-not-allowed disabled:opacity-50 disabled:bg-secondary-50
  dark:text-secondary-100 dark:disabled:bg-secondary-900
  appearance-none
  bg-no-repeat
  cursor-pointer
`.trim().replace(/\s+/g, ' ')

const normalSelectStyles = `
  border-secondary-300 bg-white
  hover:border-secondary-400
  focus:border-primary-500 focus:ring-primary-500/20
  dark:border-secondary-600 dark:bg-secondary-800 dark:hover:border-secondary-500
`.trim().replace(/\s+/g, ' ')

const errorSelectStyles = `
  border-red-500 bg-red-50
  hover:border-red-600
  focus:border-red-500 focus:ring-red-500/20
  dark:border-red-500 dark:bg-red-900/20
`.trim().replace(/\s+/g, ' ')

const ChevronIcon = () => (
  <svg
    className="h-5 w-5 text-secondary-400"
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 20 20"
    fill="currentColor"
    aria-hidden="true"
  >
    <path
      fillRule="evenodd"
      d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
      clipRule="evenodd"
    />
  </svg>
)

/**
 * Select component with label, helper text, and error state.
 *
 * @example
 * ```tsx
 * <Select label="Kategori" helperText="Urun kategorisini secin">
 *   <option value="">Seciniz</option>
 *   <option value="elektronik">Elektronik</option>
 *   <option value="giyim">Giyim</option>
 * </Select>
 *
 * <Select
 *   label="Durum"
 *   error="Lutfen bir durum secin"
 *   value={status}
 *   onChange={handleChange}
 * >
 *   <option value="">Seciniz</option>
 *   <option value="active">Aktif</option>
 *   <option value="inactive">Inaktif</option>
 * </Select>
 * ```
 */
export const Select = forwardRef<HTMLSelectElement, SelectProps>(
  (
    {
      label,
      helperText,
      error,
      fullWidth = true,
      className = '',
      id: providedId,
      children,
      ...props
    },
    ref
  ) => {
    const generatedId = useId()
    const selectId = providedId || generatedId
    const errorId = `${selectId}-error`
    const helperId = `${selectId}-helper`

    const hasError = Boolean(error)
    const selectStyles = hasError ? errorSelectStyles : normalSelectStyles

    return (
      <div className={`${fullWidth ? 'w-full' : ''}`}>
        {label && (
          <label
            htmlFor={selectId}
            className="mb-1.5 block text-sm font-medium text-secondary-700 dark:text-secondary-300"
          >
            {label}
          </label>
        )}
        <div className="relative">
          <select
            ref={ref}
            id={selectId}
            aria-invalid={hasError}
            aria-describedby={
              [hasError && errorId, helperText && helperId].filter(Boolean).join(' ') || undefined
            }
            className={`
              ${baseSelectStyles}
              ${selectStyles}
              ${className}
            `.trim().replace(/\s+/g, ' ')}
            {...props}
          >
            {children}
          </select>
          <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-3">
            <ChevronIcon />
          </div>
        </div>
        {error && (
          <p id={errorId} className="mt-1.5 text-sm text-red-600 dark:text-red-400" role="alert">
            {error}
          </p>
        )}
        {helperText && !error && (
          <p id={helperId} className="mt-1.5 text-sm text-secondary-500 dark:text-secondary-400">
            {helperText}
          </p>
        )}
      </div>
    )
  }
)

Select.displayName = 'Select'

export default Select
